-- Report Job Queue: state-machine statuses
CREATE TYPE public.report_job_status AS ENUM (
    'queued',
    'processing',
    'completed',
    'failed',
    'retrying',
    'dead_lettered'
);

-- Report Job Queue: priority tiers
CREATE TYPE public.report_job_priority AS ENUM (
    'high',
    'normal'
);

-- Durable job queue for scheduled report execution.
-- id is auto-generated by the database (gen_random_uuid).
CREATE TABLE public.report_jobs (
    id              UUID                    PRIMARY KEY DEFAULT gen_random_uuid(),
    organization_id UUID                    NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE,
    schedule_id     UUID                    REFERENCES public.report_schedules(id) ON DELETE SET NULL,
    template_id     UUID                    REFERENCES public.dashboard_templates(id) ON DELETE SET NULL,
    status          public.report_job_status NOT NULL DEFAULT 'queued',
    priority        public.report_job_priority NOT NULL DEFAULT 'normal',
    attempt_count   SMALLINT                NOT NULL DEFAULT 0,
    max_attempts    SMALLINT                NOT NULL DEFAULT 3,
    next_retry_at   TIMESTAMP WITH TIME ZONE,
    error_message   TEXT,
    created_at      TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    started_at      TIMESTAMP WITH TIME ZONE,
    completed_at    TIMESTAMP WITH TIME ZONE
);

-- Optimize: lookup by org + status (most common filter pattern)
CREATE INDEX idx_report_jobs_org_status
    ON public.report_jobs(organization_id, status);

-- Optimize: worker poll for queued jobs ordered by priority then age
CREATE INDEX idx_report_jobs_dequeue
    ON public.report_jobs(priority, created_at)
    WHERE status IN ('queued', 'retrying');

-- Optimize: retry poller (find retrying jobs past their next_retry_at)
CREATE INDEX idx_report_jobs_retry_due
    ON public.report_jobs(next_retry_at)
    WHERE status = 'retrying';

-- Optimize: DLQ size query
CREATE INDEX idx_report_jobs_dlq
    ON public.report_jobs(organization_id)
    WHERE status = 'dead_lettered';
